import org.jsoup.*;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
import java.util.*;

public class FormCheck {
    static void check(String label, Object actual, Object expected) {
        System.out.println((expected.equals(actual) ? "PASS " : "FAIL ") + label + " -> " + actual + (expected.equals(actual) ? "" : " (expected " + expected + ")"));
    }
    static List<String> kv(FormElement f) {
        List<String> out = new ArrayList<>();
        for (Connection.KeyVal kv : f.formData()) out.add(kv.key() + "=" + kv.value());
        return out;
    }
    public static void main(String[] args) {
        // 1. parser-relocated control + form-attribute control merge in document order, no dupes
        Document d1 = Jsoup.parse("<table><form id=f><tr><td><input name=a value=1></td></tr></table><input form=f name=b value=2>");
        check("mixed sources order", kv((FormElement) d1.selectFirst("form")), List.of("a=1", "b=2"));

        // 2. descendant control is also parse-linked: appears once
        Document d2 = Jsoup.parse("<form><input name=a value=1><input name=b value=2></form>");
        check("no dupes", kv((FormElement) d2.selectFirst("form")), List.of("a=1", "b=2"));

        // 3. nested disabled fieldset
        Document d3 = Jsoup.parse("<form><fieldset disabled><fieldset><input name=a value=1></fieldset></fieldset><input name=b value=2></form>");
        check("nested disabled fieldset", kv((FormElement) d3.selectFirst("form")), List.of("b=2"));

        // 4. legend of inner disabled fieldset, inside first legend of outer disabled fieldset
        Document d4 = Jsoup.parse("<form><fieldset disabled><legend><input name=a value=1></legend></fieldset></form>");
        check("first legend exception", kv((FormElement) d4.selectFirst("form")), List.of("a=1"));

        // 5. removal of linked (parse-relocated) control stops its submission
        Document d5 = Jsoup.parse("<table><form><tr><td><input name=a value=1></td></tr></form></table>");
        FormElement f5 = (FormElement) d5.selectFirst("form");
        check("linked before remove", kv(f5), List.of("a=1"));
        d5.selectFirst("input").remove();
        check("linked after remove", kv(f5), List.of());

        // 6. control moved into another form loses association
        Document d6 = Jsoup.parse("<form id=f1><input name=a value=1></form><form id=f2></form>");
        FormElement f1 = (FormElement) d6.getElementById("f1");
        FormElement f2 = (FormElement) d6.getElementById("f2");
        f2.appendChild(d6.selectFirst("input"));
        check("moved out of f1", kv(f1), List.of());
        check("moved into f2", kv(f2), List.of("a=1"));

        // 7. radio/checkbox unchanged; empty form; document intact
        Document d7 = Jsoup.parse("<form><input type=radio name=r value=x checked><input type=radio name=r value=y></form>");
        check("radio", kv((FormElement) d7.selectFirst("form")), List.of("r=x"));

        // 8. form attribute pointing at a non-form element is invalid
        Document d8 = Jsoup.parse("<div id=x></div><form><input name=a value=1 form=x></form>");
        check("form attr to non-form", kv((FormElement) d8.selectFirst("form")), List.of());

        // 9. textarea and text input unchanged
        Document d9 = Jsoup.parse("<form><textarea name=t>hello</textarea><input name=i value=v></form>");
        check("textarea+input", kv((FormElement) d9.selectFirst("form")), List.of("t=hello", "i=v"));

        // 10. select inside disabled fieldset excluded entirely
        Document d10 = Jsoup.parse("<form><fieldset disabled><select name=s><option value=a></select></fieldset></form>");
        check("select in disabled fieldset", kv((FormElement) d10.selectFirst("form")), List.of());
    }
}
